import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const aiEnabled = process.env.GITBOR_AI !== '0';
const flavor = aiEnabled ? 'standard' : 'no-ai';
const productName = aiEnabled ? 'GitBor' : 'GitBor No AI';

const out = `/**
 * Build-time feature flags.
 *
 * Generated by scripts/write-build-flags.mjs. Do not edit build values by hand.
 */
export const AI_ENABLED = ${aiEnabled};
export const BUILD_FLAVOR = '${flavor}' as const;
export const PRODUCT_NAME = '${productName}';
`;

writeFileSync(resolve('src/core/buildFlags.ts'), out, 'utf8');
console.log(`[build-flags] AI_ENABLED=${aiEnabled} BUILD_FLAVOR=${flavor}`);
